CREATE OR REPLACE FUNCTION public.review_points_transaction(p_id uuid,p_actor text,p_approve boolean,p_reason text DEFAULT '') RETURNS public."Points_Transactions" LANGUAGE plpgsql SET search_path=public AS $$ DECLARE tx public."Points_Transactions"; self_allowed boolean; BEGIN SELECT * INTO tx FROM public."Points_Transactions" WHERE id=p_id FOR UPDATE; IF NOT FOUND OR tx.status<>'Pending' THEN RAISE EXCEPTION 'Transaction unavailable or reviewed'; END IF; IF NOT public.evaluation_can(p_actor,'points_approval','e',tx.team_id) THEN RAISE EXCEPTION 'Not authorized'; END IF; SELECT coalesce(bool_or(allow_self_approval),false) INTO self_allowed FROM public."Evaluation_Permissions" WHERE user_id=p_actor AND screen='points_approval' AND actions LIKE '%r%' AND actions LIKE '%e%' AND (general_access OR (team_id<>'' AND team_id=tx.team_id)); IF (tx.submitted_by=p_actor OR tx.user_id=p_actor) AND NOT self_allowed THEN RAISE EXCEPTION 'Self approval not permitted'; END IF; IF NOT p_approve AND length(btrim(coalesce(p_reason,'')))=0 THEN RAISE EXCEPTION 'Rejection reason required'; END IF; UPDATE public."Points_Transactions" SET status=CASE WHEN p_approve THEN 'Approved' ELSE 'Rejected' END,reviewed_by=p_actor,reviewed_at=now(),rejection_reason=CASE WHEN p_approve THEN NULL ELSE p_reason END WHERE id=p_id RETURNING * INTO tx; RETURN tx; END $$;
CREATE OR REPLACE FUNCTION public.evaluation_review_batch(p_ids uuid[],p_actor text,p_approve boolean,p_reason text DEFAULT '') RETURNS integer LANGUAGE plpgsql SET search_path=public AS $$ DECLARE x uuid; n integer:=0; BEGIN FOREACH x IN ARRAY p_ids LOOP PERFORM public.review_points_transaction(x,p_actor,p_approve,p_reason); n:=n+1; END LOOP; RETURN n; END $$;
CREATE OR REPLACE FUNCTION public.evaluation_rankings(p_category text,p_season text DEFAULT '') RETURNS TABLE(user_id text,team_id text,total numeric,overall_rank bigint,stage_rank bigint) LANGUAGE sql STABLE SET search_path=public AS $$ WITH totals AS (SELECT u."ID" AS uid,coalesce(u."Team_ID",'') AS tid,coalesce(sum(t.amount),0) AS score FROM public."Users" u LEFT JOIN public."Points_Transactions" t ON t.user_id=u."ID" AND t.category=p_category AND t.status='Approved' AND (p_season='' OR t.season=p_season) WHERE (CASE WHEN u."Role"='Leader' THEN 'Leader' ELSE 'Member' END)=p_category AND coalesce(u."Status",'Active') NOT IN ('Pending','Suspended') GROUP BY u."ID",u."Team_ID") SELECT uid,tid,score,rank() OVER(ORDER BY score DESC),rank() OVER(PARTITION BY tid ORDER BY score DESC) FROM totals ORDER BY score DESC,uid $$;
CREATE OR REPLACE FUNCTION public.evaluation_guard_result() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Evaluation history is immutable'; END $$;
CREATE TRIGGER evaluation_results_immutable BEFORE UPDATE OR DELETE ON public."Evaluation_Results" FOR EACH ROW EXECUTE FUNCTION public.evaluation_guard_result(); CREATE TRIGGER evaluation_audit_immutable BEFORE UPDATE OR DELETE ON public."Points_Audit" FOR EACH ROW EXECUTE FUNCTION public.evaluation_guard_result(); CREATE TRIGGER evaluation_changes_immutable BEFORE UPDATE OR DELETE ON public."Evaluation_Changes" FOR EACH ROW EXECUTE FUNCTION public.evaluation_guard_result();
REVOKE ALL ON FUNCTION public.evaluation_review_batch(uuid[],text,boolean,text),public.evaluation_rankings(text,text),public.evaluation_guard_result() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.evaluation_review_batch(uuid[],text,boolean,text),public.evaluation_rankings(text,text) TO service_role;